    if(!data){ box.hidden=true; return }
    const pipsEl=$('#calcPips'); if(pipsEl) pipsEl.textContent=`${data.pips>0?'+':''}${Number(data.pips.toFixed(1))}`;
    const grossEl=$('#calcGross'); if(grossEl){ grossEl.textContent=fmtSignedMoney(data.gross); grossEl.className=data.gross>0?'positive':data.gross<0?'negative':'' }
    const netEl=$('#calcNet'); if(netEl){ netEl.textContent=fmtSignedMoney(data.net); netEl.className=data.net>0?'positive':data.net<0?'negative':'' }
