      const entry = $('#entryPrice').value, exit = $('#exitPrice').value;
      const qty = Number($('#quantity').value || 0);
      const pipEl = $('#tradePips'), pnlEl = $('#pnl');
      if (!sym || entry === '' || exit === '' || !qty) { if (pipEl) pipEl.value = ''; updateCalcSummary(null); return }
      const spec = getSpec(sym);
      const pips = calcPips({ direction: dir, entryPrice: Number(entry), currentPrice: Number(exit), spec });
      if (pipEl) pipEl.value = Number(pips.toFixed(1));
      const gross = calcMoney({ pips, spec, quantity: qty });
      const net = calcNet({ gross, commission: $('#commission').value, swap: $('#swap').value, fees: $('#fees').value });
